const codes = {
  100: ["Continue", "Client should continue with its request."],
  200: ["OK", "The request succeeded."],
  201: ["Created", "The request succeeded and a new resource was created."],
  301: ["Moved Permanently", "The resource has moved to a new permanent URL."],
  302: ["Found", "The resource temporarily resides at a different URL."],
  400: ["Bad Request", "The server cannot process the malformed request."],
  401: ["Unauthorized", "Authentication is required and has failed or not been provided."],
  403: ["Forbidden", "The server refuses to authorize the request."],
  404: ["Not Found", "The requested resource could not be found."],
  500: ["Internal Server Error", "The server encountered an unexpected condition."],
  503: ["Service Unavailable", "The server is temporarily unable to handle the request."],
  418: ["I'm a teapot", "The server refuses to brew coffee because it is, permanently, a teapot (RFC 2324, reserved in RFC 9110)."]
};
function lookup() {
  const v = document.getElementById("code").value.trim();
  const r = document.getElementById("result");
  const c = codes[v];
  r.innerHTML = c ? `<h2>${v} ${c[0]}</h2><p>${c[1]}</p>` : `<p>Unknown status code: ${v}</p>`;
}
document.getElementById("btn").addEventListener("click", lookup);
document.getElementById("code").addEventListener("keydown", e => { if (e.key === "Enter") lookup(); });

